import subprocess
from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/api/grep', methods=['GET'])
def grep_log():
    pattern = request.args.get('pattern', '')
    cmd = ['sh', '-c', f"grep '{pattern}' /var/log/app.log"]
    result = subprocess.run(cmd, capture_output=True, text=True)
    return jsonify({'result': result.stdout})

import org.springframework.expression.spel.standard.SpelExpressionParser;

public class ConfigService {
    private final SpelExpressionParser parser = new SpelExpressionParser();

    public String resolveConfig(String expression, ConfigObject config) {
        return parser.parseExpression(expression).getValue(config, String.class);
    }
}

import org.springframework.expression.spel.standard.SpelExpressionParser;

public class SpelGuard {
    private final SpelExpressionParser parser = new SpelExpressionParser();

    public Object safeEval(String expression) {
        String filtered = expression.replace("T(", "").replace("Runtime", "");
        return parser.parseExpression(filtered).getValue();
    }
}
